EXPENSE_CLAIM_PAYABLE_NAME = "Employee Reimbursements Payable"


def backfill_expense_claim_payable(apps, schema_editor):
    """Give every existing HR Settings row its expense claim payable account.

    Same rule as ``hr.services.setup.ensure_hr_setup``: an existing account of that
    name is reused, else a liability leaf is created under the company's top-level
    liability group.  Migrations must not import service code, so it is repeated here.
    """
    Account = apps.get_model("accounts", "Account")
    HRSettings = apps.get_model("hr", "HRSettings")
    for settings_row in HRSettings.objects.all():
        company_id = settings_row.company_id
        account = Account.objects.filter(
            company_id=company_id, name=EXPENSE_CLAIM_PAYABLE_NAME
        ).first()
        if account is None:
            groups = Account.objects.filter(
                company_id=company_id, root_type="Liability", is_group=True
            )
            parent = (
                groups.filter(parent__isnull=True).order_by("pk").first()
                or groups.order_by("pk").first()
            )
            account = Account.objects.create(
                company_id=company_id,
                name=EXPENSE_CLAIM_PAYABLE_NAME,
                parent=parent,
                root_type="Liability",
                account_type=None,
                is_group=False,
            )
        settings_row.expense_claim_payable_account = account
        settings_row.save(update_fields=["expense_claim_payable_account"])


